-- ===========================
-- 物料管理模块数据库表脚本
-- ===========================

-- ----------------------------
-- Table structure for material
-- ----------------------------
DROP TABLE IF EXISTS `material`;
CREATE TABLE `material` (
  `id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新日期',
  `sys_org_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '所属部门',
  `tenant_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '租户id',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '物料名称',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '物料类型（component=组件，template=模板）',
  `version` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '1.0.0' COMMENT '版本号',
  `code` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '代码内容',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '内容描述',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '描述信息',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'active' COMMENT '状态（active=启用，inactive=禁用）',
  `version_lock` int NULL DEFAULT 0 COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_name_type` (`name`, `type`) USING BTREE COMMENT '名称和类型唯一索引',
  KEY `idx_name` (`name`) USING BTREE COMMENT '名称索引',
  KEY `idx_type` (`type`) USING BTREE COMMENT '类型索引',
  KEY `idx_status` (`status`) USING BTREE COMMENT '状态索引',
  KEY `idx_version` (`version`) USING BTREE COMMENT '版本索引'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '物料信息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of material (示例数据)
-- ----------------------------
INSERT INTO `material` VALUES 
('1', 'admin', '2024-01-01 10:00:00', 'admin', '2024-01-01 10:00:00', 'A01', NULL, 'BasicTable', 'component', '1.0.0', 
'<template>\n  <div class="basic-table">\n    <a-table\n      :columns="columns"\n      :data-source="dataSource"\n      :pagination="pagination"\n      @change="handleTableChange"\n    />\n  </div>\n</template>\n\n<script setup>\nimport { ref, reactive } from \'vue\'\n\nconst columns = ref([\n  { title: \'姓名\', dataIndex: \'name\', key: \'name\' },\n  { title: \'年龄\', dataIndex: \'age\', key: \'age\' },\n  { title: \'地址\', dataIndex: \'address\', key: \'address\' }\n])\n\nconst dataSource = ref([])\nconst pagination = reactive({\n  current: 1,\n  pageSize: 10,\n  total: 0\n})\n\nconst handleTableChange = (pag) => {\n  pagination.current = pag.current\n  pagination.pageSize = pag.pageSize\n}\n</script>', 
'基础表格组件，支持分页、排序等功能', '通用的数据表格组件，适用于各种列表展示场景', 'active', 0),

('2', 'admin', '2024-01-01 10:00:00', 'admin', '2024-01-01 10:00:00', 'A01', NULL, 'FormBuilder', 'component', '1.0.0',
'<template>\n  <div class="form-builder">\n    <a-form\n      :model="formData"\n      :rules="rules"\n      :label-col="{ span: 6 }"\n      :wrapper-col="{ span: 18 }"\n    >\n      <a-form-item\n        v-for="field in fields"\n        :key="field.name"\n        :label="field.label"\n        :name="field.name"\n      >\n        <component\n          :is="field.component"\n          v-model:value="formData[field.name]"\n          v-bind="field.props"\n        />\n      </a-form-item>\n    </a-form>\n  </div>\n</template>\n\n<script setup>\nimport { ref, reactive } from \'vue\'\n\nconst props = defineProps({\n  fields: {\n    type: Array,\n    default: () => []\n  }\n})\n\nconst formData = reactive({})\nconst rules = reactive({})\n</script>',
'动态表单构建器组件', '可根据配置动态生成表单的组件，支持多种表单控件', 'active', 0),

('3', 'admin', '2024-01-01 10:00:00', 'admin', '2024-01-01 10:00:00', 'A01', NULL, 'ChartWidget', 'component', '1.0.0',
'<template>\n  <div class="chart-widget">\n    <div class="chart-header">\n      <h3>{{ title }}</h3>\n    </div>\n    <div class="chart-content" ref="chartRef"></div>\n  </div>\n</template>\n\n<script setup>\nimport { ref, onMounted, watch } from \'vue\'\nimport * as echarts from \'echarts\'\n\nconst props = defineProps({\n  title: String,\n  option: Object,\n  height: {\n    type: String,\n    default: \'300px\'\n  }\n})\n\nconst chartRef = ref()\nlet chartInstance = null\n\nonMounted(() => {\n  initChart()\n})\n\nconst initChart = () => {\n  chartInstance = echarts.init(chartRef.value)\n  chartInstance.setOption(props.option)\n}\n\nwatch(() => props.option, (newOption) => {\n  if (chartInstance) {\n    chartInstance.setOption(newOption)\n  }\n}, { deep: true })\n</script>',
'图表组件，基于ECharts', '通用的图表展示组件，支持各种类型的图表', 'active', 0),

('4', 'admin', '2024-01-01 10:00:00', 'admin', '2024-01-01 10:00:00', 'A01', NULL, 'LayoutGrid', 'component', '1.0.0',
'<template>\n  <div class="layout-grid">\n    <a-row :gutter="gutter">\n      <a-col\n        v-for="(item, index) in items"\n        :key="index"\n        :span="item.span || defaultSpan"\n        :xs="item.xs"\n        :sm="item.sm"\n        :md="item.md"\n        :lg="item.lg"\n        :xl="item.xl"\n      >\n        <div class="grid-item">\n          <slot :name="`item-${index}`" :item="item" :index="index">\n            {{ item.content }}\n          </slot>\n        </div>\n      </a-col>\n    </a-row>\n  </div>\n</template>\n\n<script setup>\nconst props = defineProps({\n  items: {\n    type: Array,\n    default: () => []\n  },\n  gutter: {\n    type: Number,\n    default: 16\n  },\n  defaultSpan: {\n    type: Number,\n    default: 6\n  }\n})\n</script>',
'响应式网格布局组件', '基于Ant Design的栅格系统，支持响应式布局', 'active', 0),

('5', 'admin', '2024-01-01 10:00:00', 'admin', '2024-01-01 10:00:00', 'A01', NULL, 'DataFilter', 'component', '1.0.0',
'<template>\n  <div class="data-filter">\n    <a-form\n      :model="filterForm"\n      layout="inline"\n      @finish="handleSearch"\n    >\n      <a-form-item\n        v-for="filter in filters"\n        :key="filter.key"\n        :label="filter.label"\n        :name="filter.key"\n      >\n        <component\n          :is="getFilterComponent(filter.type)"\n          v-model:value="filterForm[filter.key]"\n          v-bind="filter.props"\n          :placeholder="filter.placeholder"\n        />\n      </a-form-item>\n      <a-form-item>\n        <a-button type="primary" html-type="submit">搜索</a-button>\n        <a-button @click="handleReset" style="margin-left: 8px">重置</a-button>\n      </a-form-item>\n    </a-form>\n  </div>\n</template>\n\n<script setup>\nimport { reactive } from \'vue\'\n\nconst props = defineProps({\n  filters: {\n    type: Array,\n    default: () => []\n  }\n})\n\nconst emit = defineEmits([\'search\', \'reset\'])\n\nconst filterForm = reactive({})\n\nconst getFilterComponent = (type) => {\n  const componentMap = {\n    input: \'a-input\',\n    select: \'a-select\',\n    date: \'a-date-picker\',\n    dateRange: \'a-range-picker\'\n  }\n  return componentMap[type] || \'a-input\'\n}\n\nconst handleSearch = () => {\n  emit(\'search\', filterForm)\n}\n\nconst handleReset = () => {\n  Object.keys(filterForm).forEach(key => {\n    filterForm[key] = undefined\n  })\n  emit(\'reset\')\n}\n</script>',
'数据过滤器组件', '通用的数据筛选组件，支持多种筛选条件', 'active', 0),

('6', 'admin', '2024-01-01 10:00:00', 'admin', '2024-01-01 10:00:00', 'A02', NULL, '用户管理页面', 'template', '1.0.0',
'<template>\n  <div class="user-management">\n    <div class="page-header">\n      <h2>用户管理</h2>\n      <a-button type="primary" @click="handleAdd">新增用户</a-button>\n    </div>\n    \n    <DataFilter\n      :filters="filterConfig"\n      @search="handleSearch"\n      @reset="handleReset"\n    />\n    \n    <BasicTable\n      :columns="columns"\n      :data-source="dataSource"\n      :pagination="pagination"\n      @change="handleTableChange"\n    />\n    \n    <a-modal\n      v-model:visible="modalVisible"\n      :title="modalTitle"\n      @ok="handleSubmit"\n      @cancel="handleCancel"\n    >\n      <FormBuilder :fields="formFields" ref="formRef" />\n    </a-modal>\n  </div>\n</template>\n\n<script setup>\nimport { ref, reactive, onMounted } from \'vue\'\nimport BasicTable from \'@/components/BasicTable.vue\'\nimport FormBuilder from \'@/components/FormBuilder.vue\'\nimport DataFilter from \'@/components/DataFilter.vue\'\n\n// 表格列配置\nconst columns = ref([\n  { title: \'用户名\', dataIndex: \'username\', key: \'username\' },\n  { title: \'姓名\', dataIndex: \'realname\', key: \'realname\' },\n  { title: \'邮箱\', dataIndex: \'email\', key: \'email\' },\n  { title: \'状态\', dataIndex: \'status\', key: \'status\' },\n  { title: \'操作\', key: \'action\', width: 200 }\n])\n\n// 数据源\nconst dataSource = ref([])\nconst pagination = reactive({\n  current: 1,\n  pageSize: 10,\n  total: 0\n})\n\n// 筛选配置\nconst filterConfig = ref([\n  { key: \'username\', label: \'用户名\', type: \'input\', placeholder: \'请输入用户名\' },\n  { key: \'status\', label: \'状态\', type: \'select\', props: { options: [{ label: \'启用\', value: 1 }, { label: \'禁用\', value: 0 }] } }\n])\n\n// 表单配置\nconst formFields = ref([\n  { name: \'username\', label: \'用户名\', component: \'a-input\', props: { placeholder: \'请输入用户名\' } },\n  { name: \'realname\', label: \'姓名\', component: \'a-input\', props: { placeholder: \'请输入姓名\' } },\n  { name: \'email\', label: \'邮箱\', component: \'a-input\', props: { placeholder: \'请输入邮箱\' } }\n])\n\n// 模态框\nconst modalVisible = ref(false)\nconst modalTitle = ref(\'新增用户\')\nconst formRef = ref()\n\n// 事件处理\nconst handleAdd = () => {\n  modalTitle.value = \'新增用户\'\n  modalVisible.value = true\n}\n\nconst handleSearch = (filters) => {\n  console.log(\'搜索条件:\', filters)\n  // 实现搜索逻辑\n}\n\nconst handleReset = () => {\n  console.log(\'重置筛选条件\')\n  // 实现重置逻辑\n}\n\nconst handleTableChange = (pag) => {\n  pagination.current = pag.current\n  pagination.pageSize = pag.pageSize\n  // 重新加载数据\n}\n\nconst handleSubmit = () => {\n  // 提交表单逻辑\n  modalVisible.value = false\n}\n\nconst handleCancel = () => {\n  modalVisible.value = false\n}\n\nonMounted(() => {\n  // 初始化数据\n})\n</script>',
'完整的用户管理页面模板', '包含用户列表、搜索、新增、编辑等功能的完整页面模板', 'active', 0),

('7', 'admin', '2024-01-01 10:00:00', 'admin', '2024-01-01 10:00:00', 'A02', NULL, '数据看板模板', 'template', '1.0.0',
'<template>\n  <div class="dashboard">\n    <div class="dashboard-header">\n      <h2>数据看板</h2>\n      <a-date-picker v-model:value="selectedDate" @change="handleDateChange" />\n    </div>\n    \n    <LayoutGrid :items="gridItems" :gutter="24">\n      <template #item-0="{ item }">\n        <div class="stat-card">\n          <div class="stat-title">{{ item.title }}</div>\n          <div class="stat-value">{{ item.value }}</div>\n          <div class="stat-trend">{{ item.trend }}</div>\n        </div>\n      </template>\n      \n      <template #item-1="{ item }">\n        <ChartWidget :title="item.title" :option="item.chartOption" />\n      </template>\n      \n      <template #item-2="{ item }">\n        <ChartWidget :title="item.title" :option="item.chartOption" />\n      </template>\n      \n      <template #item-3="{ item }">\n        <BasicTable :columns="item.columns" :data-source="item.dataSource" />\n      </template>\n    </LayoutGrid>\n  </div>\n</template>\n\n<script setup>\nimport { ref, reactive, onMounted } from \'vue\'\nimport LayoutGrid from \'@/components/LayoutGrid.vue\'\nimport ChartWidget from \'@/components/ChartWidget.vue\'\nimport BasicTable from \'@/components/BasicTable.vue\'\n\nconst selectedDate = ref()\n\nconst gridItems = ref([\n  {\n    span: 6,\n    title: \'总用户数\',\n    value: \'12,345\',\n    trend: \'↑ 12.5%\'\n  },\n  {\n    span: 12,\n    title: \'用户增长趋势\',\n    chartOption: {\n      xAxis: { type: \'category\', data: [\'Mon\', \'Tue\', \'Wed\', \'Thu\', \'Fri\', \'Sat\', \'Sun\'] },\n      yAxis: { type: \'value\' },\n      series: [{ data: [120, 200, 150, 80, 70, 110, 130], type: \'line\' }]\n    }\n  },\n  {\n    span: 6,\n    title: \'数据分布\',\n    chartOption: {\n      series: [{\n        type: \'pie\',\n        data: [\n          { value: 335, name: \'类型A\' },\n          { value: 310, name: \'类型B\' },\n          { value: 234, name: \'类型C\' }\n        ]\n      }]\n    }\n  },\n  {\n    span: 24,\n    columns: [\n      { title: \'排名\', dataIndex: \'rank\', key: \'rank\' },\n      { title: \'名称\', dataIndex: \'name\', key: \'name\' },\n      { title: \'数值\', dataIndex: \'value\', key: \'value\' }\n    ],\n    dataSource: [\n      { rank: 1, name: \'项目A\', value: 1000 },\n      { rank: 2, name: \'项目B\', value: 800 },\n      { rank: 3, name: \'项目C\', value: 600 }\n    ]\n  }\n])\n\nconst handleDateChange = (date) => {\n  console.log(\'日期变更:\', date)\n  // 根据日期重新加载数据\n}\n\nonMounted(() => {\n  // 初始化数据\n})\n</script>\n\n<style scoped>\n.stat-card {\n  padding: 20px;\n  background: #fff;\n  border-radius: 8px;\n  box-shadow: 0 2px 8px rgba(0,0,0,0.1);\n}\n\n.stat-title {\n  font-size: 14px;\n  color: #666;\n  margin-bottom: 8px;\n}\n\n.stat-value {\n  font-size: 24px;\n  font-weight: bold;\n  color: #333;\n  margin-bottom: 4px;\n}\n\n.stat-trend {\n  font-size: 12px;\n  color: #52c41a;\n}\n</style>',
'数据看板页面模板', '包含统计卡片、图表、表格等多种数据展示形式的看板模板', 'active', 0),

('8', 'admin', '2024-01-01 10:00:00', 'admin', '2024-01-01 10:00:00', 'A02', NULL, '表单页面模板', 'template', '1.0.0',
'<template>\n  <div class="form-page">\n    <div class="page-header">\n      <h2>{{ pageTitle }}</h2>\n    </div>\n    \n    <div class="form-container">\n      <a-card title="基本信息">\n        <FormBuilder :fields="basicFields" ref="basicFormRef" />\n      </a-card>\n      \n      <a-card title="详细信息" style="margin-top: 16px;">\n        <FormBuilder :fields="detailFields" ref="detailFormRef" />\n      </a-card>\n      \n      <div class="form-actions">\n        <a-button @click="handleCancel">取消</a-button>\n        <a-button type="primary" @click="handleSubmit" :loading="submitting">提交</a-button>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup>\nimport { ref, reactive } from \'vue\'\nimport FormBuilder from \'@/components/FormBuilder.vue\'\n\nconst pageTitle = ref(\'表单页面\')\nconst submitting = ref(false)\n\n// 基本信息表单配置\nconst basicFields = ref([\n  { name: \'name\', label: \'名称\', component: \'a-input\', props: { placeholder: \'请输入名称\' } },\n  { name: \'type\', label: \'类型\', component: \'a-select\', props: { \n    options: [\n      { label: \'类型1\', value: \'type1\' },\n      { label: \'类型2\', value: \'type2\' }\n    ],\n    placeholder: \'请选择类型\'\n  }},\n  { name: \'status\', label: \'状态\', component: \'a-radio-group\', props: {\n    options: [\n      { label: \'启用\', value: 1 },\n      { label: \'禁用\', value: 0 }\n    ]\n  }}\n])\n\n// 详细信息表单配置\nconst detailFields = ref([\n  { name: \'description\', label: \'描述\', component: \'a-textarea\', props: { \n    rows: 4,\n    placeholder: \'请输入描述信息\'\n  }},\n  { name: \'startDate\', label: \'开始日期\', component: \'a-date-picker\', props: { \n    placeholder: \'请选择开始日期\'\n  }},\n  { name: \'endDate\', label: \'结束日期\', component: \'a-date-picker\', props: { \n    placeholder: \'请选择结束日期\'\n  }},\n  { name: \'tags\', label: \'标签\', component: \'a-select\', props: {\n    mode: \'tags\',\n    placeholder: \'请输入标签\'\n  }}\n])\n\nconst basicFormRef = ref()\nconst detailFormRef = ref()\n\nconst handleSubmit = async () => {\n  try {\n    submitting.value = true\n    \n    // 获取表单数据\n    const basicData = basicFormRef.value?.getFormData()\n    const detailData = detailFormRef.value?.getFormData()\n    \n    const formData = {\n      ...basicData,\n      ...detailData\n    }\n    \n    console.log(\'提交数据:\', formData)\n    \n    // 这里添加提交逻辑\n    await new Promise(resolve => setTimeout(resolve, 1000))\n    \n    // 提交成功后的处理\n    console.log(\'提交成功\')\n    \n  } catch (error) {\n    console.error(\'提交失败:\', error)\n  } finally {\n    submitting.value = false\n  }\n}\n\nconst handleCancel = () => {\n  // 取消操作，可以返回上一页或清空表单\n  console.log(\'取消操作\')\n}\n</script>\n\n<style scoped>\n.form-container {\n  max-width: 800px;\n  margin: 0 auto;\n}\n\n.form-actions {\n  margin-top: 24px;\n  text-align: center;\n}\n\n.form-actions .ant-btn {\n  margin: 0 8px;\n}\n</style>',
'通用表单页面模板', '包含多个表单区块、提交取消操作的完整表单页面模板', 'active', 0),

('9', 'admin', '2024-01-01 10:00:00', 'admin', '2024-01-01 10:00:00', 'A02', NULL, '卡片布局模板', 'template', '1.0.0',
'<template>\n  <div class="card-layout">\n    <div class="page-header">\n      <h2>卡片布局</h2>\n      <div class="header-actions">\n        <a-input-search\n          v-model:value="searchKeyword"\n          placeholder="搜索卡片"\n          @search="handleSearch"\n          style="width: 200px; margin-right: 16px;"\n        />\n        <a-button type="primary" @click="handleAdd">新增卡片</a-button>\n      </div>\n    </div>\n    \n    <DataFilter\n      :filters="filterConfig"\n      @search="handleFilter"\n      @reset="handleFilterReset"\n    />\n    \n    <LayoutGrid :items="cardItems" :gutter="16" :default-span="8">\n      <template #item-0="{ item, index }" v-for="(item, index) in cardItems" :key="index">\n        <a-card\n          :title="item.title"\n          :extra="cardExtra"\n          hoverable\n          @click="handleCardClick(item)"\n        >\n          <template #extra>\n            <a-dropdown>\n              <a-button type="text" size="small">\n                <MoreOutlined />\n              </a-button>\n              <template #overlay>\n                <a-menu @click="handleMenuClick($event, item)">\n                  <a-menu-item key="edit">编辑</a-menu-item>\n                  <a-menu-item key="delete">删除</a-menu-item>\n                </a-menu>\n              </template>\n            </a-dropdown>\n          </template>\n          \n          <div class="card-content">\n            <div class="card-image" v-if="item.image">\n              <img :src="item.image" :alt="item.title" />\n            </div>\n            <div class="card-description">{{ item.description }}</div>\n            <div class="card-meta">\n              <a-tag :color="item.statusColor">{{ item.status }}</a-tag>\n              <span class="card-date">{{ item.updateTime }}</span>\n            </div>\n          </div>\n        </a-card>\n      </template>\n    </LayoutGrid>\n    \n    <div class="pagination-wrapper" v-if="pagination.total > 0">\n      <a-pagination\n        v-model:current="pagination.current"\n        v-model:page-size="pagination.pageSize"\n        :total="pagination.total"\n        show-size-changer\n        show-quick-jumper\n        @change="handlePageChange"\n        @show-size-change="handlePageSizeChange"\n      />\n    </div>\n  </div>\n</template>\n\n<script setup>\nimport { ref, reactive, onMounted } from \'vue\'\nimport { MoreOutlined } from \'@ant-design/icons-vue\'\nimport LayoutGrid from \'@/components/LayoutGrid.vue\'\nimport DataFilter from \'@/components/DataFilter.vue\'\n\nconst searchKeyword = ref(\'\')\n\n// 筛选配置\nconst filterConfig = ref([\n  { key: \'category\', label: \'分类\', type: \'select\', props: { \n    options: [\n      { label: \'全部\', value: \'\' },\n      { label: \'分类1\', value: \'cat1\' },\n      { label: \'分类2\', value: \'cat2\' }\n    ]\n  }},\n  { key: \'status\', label: \'状态\', type: \'select\', props: {\n    options: [\n      { label: \'全部\', value: \'\' },\n      { label: \'启用\', value: \'active\' },\n      { label: \'禁用\', value: \'inactive\' }\n    ]\n  }},\n  { key: \'dateRange\', label: \'日期范围\', type: \'dateRange\' }\n])\n\n// 卡片数据\nconst cardItems = ref([\n  {\n    title: \'卡片标题1\',\n    description: \'这是卡片的描述信息，可以包含更多详细内容...\',\n    image: \'https://via.placeholder.com/300x200\',\n    status: \'启用\',\n    statusColor: \'green\',\n    updateTime: \'2024-01-01\',\n    category: \'cat1\'\n  },\n  {\n    title: \'卡片标题2\',\n    description: \'另一个卡片的描述信息...\',\n    image: \'https://via.placeholder.com/300x200\',\n    status: \'禁用\',\n    statusColor: \'red\',\n    updateTime: \'2024-01-02\',\n    category: \'cat2\'\n  }\n  // 更多卡片数据...\n])\n\n// 分页配置\nconst pagination = reactive({\n  current: 1,\n  pageSize: 12,\n  total: 0\n})\n\n// 事件处理\nconst handleSearch = (value) => {\n  console.log(\'搜索:\', value)\n  // 实现搜索逻辑\n}\n\nconst handleAdd = () => {\n  console.log(\'新增卡片\')\n  // 实现新增逻辑\n}\n\nconst handleFilter = (filters) => {\n  console.log(\'筛选条件:\', filters)\n  // 实现筛选逻辑\n}\n\nconst handleFilterReset = () => {\n  console.log(\'重置筛选\')\n  // 实现重置逻辑\n}\n\nconst handleCardClick = (item) => {\n  console.log(\'点击卡片:\', item)\n  // 实现卡片点击逻辑\n}\n\nconst handleMenuClick = ({ key }, item) => {\n  console.log(\'菜单操作:\', key, item)\n  if (key === \'edit\') {\n    // 编辑逻辑\n  } else if (key === \'delete\') {\n    // 删除逻辑\n  }\n}\n\nconst handlePageChange = (page, pageSize) => {\n  pagination.current = page\n  pagination.pageSize = pageSize\n  // 重新加载数据\n}\n\nconst handlePageSizeChange = (current, size) => {\n  pagination.current = 1\n  pagination.pageSize = size\n  // 重新加载数据\n}\n\nonMounted(() => {\n  // 初始化数据\n  pagination.total = cardItems.value.length\n})\n</script>\n\n<style scoped>\n.page-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 16px;\n}\n\n.header-actions {\n  display: flex;\n  align-items: center;\n}\n\n.card-content {\n  min-height: 200px;\n}\n\n.card-image {\n  margin-bottom: 12px;\n}\n\n.card-image img {\n  width: 100%;\n  height: 150px;\n  object-fit: cover;\n  border-radius: 4px;\n}\n\n.card-description {\n  margin-bottom: 12px;\n  color: #666;\n  line-height: 1.5;\n}\n\n.card-meta {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.card-date {\n  color: #999;\n  font-size: 12px;\n}\n\n.pagination-wrapper {\n  margin-top: 24px;\n  text-align: center;\n}\n</style>',
'卡片布局页面模板', '适用于展示产品、项目、文章等内容的卡片式布局模板', 'active', 0);

-- ----------------------------
-- 创建相关索引以优化查询性能
-- ----------------------------
-- 复合索引：类型+状态
CREATE INDEX `idx_type_status` ON `material` (`type`, `status`) USING BTREE;

-- 复合索引：名称+版本
CREATE INDEX `idx_name_version` ON `material` (`name`, `version`) USING BTREE;

-- 全文索引：内容搜索（如果需要）
-- ALTER TABLE `material` ADD FULLTEXT(`content`, `description`) WITH PARSER ngram;

-- ----------------------------
-- 表注释和字段注释说明
-- ----------------------------
/*
物料信息表 (material) 字段说明：
- id: 主键ID，使用UUID格式
- create_by: 创建人，记录数据创建者
- create_time: 创建时间，记录数据创建时间
- update_by: 更新人，记录最后更新者
- update_time: 更新时间，记录最后更新时间
- sys_org_code: 所属部门编码，用于数据权限控制
- tenant_id: 租户ID，用于多租户数据隔离
- name: 物料名称，必填字段，与type组成唯一约束
- type: 物料类型，component表示组件，template表示模板
- version: 版本号，默认为1.0.0，支持版本管理
- code: 代码内容，存储组件或模板的具体代码
- content: 内容描述，存储物料的详细说明
- description: 描述信息，简短的物料描述
- status: 物料状态，active表示启用，inactive表示禁用
- version_lock: 乐观锁版本号，用于并发控制

索引说明：
- uk_name_type: 名称和类型的唯一索引，确保同类型下名称唯一
- idx_name: 名称索引，优化按名称查询
- idx_type: 类型索引，优化按类型筛选
- idx_status: 状态索引，优化按状态筛选
- idx_version: 版本索引，优化版本查询
- idx_type_status: 类型和状态复合索引，优化组合查询
- idx_name_version: 名称和版本复合索引，优化版本管理查询
*/